import { AnimatePresence, motion } from 'framer-motion';
import React, { forwardRef, useRef } from 'react';
import styled, { CSSObject } from 'styled-components';

import AnimationsJS from '@dynatrace/strato-design-tokens/animations-js';
import Borders from '@dynatrace/strato-design-tokens/borders';
import BoxShadows from '@dynatrace/strato-design-tokens/box-shadows';
import Colors from '@dynatrace/strato-design-tokens/colors';
import Elevations from '@dynatrace/strato-design-tokens/elevations';

import { FocusScope } from '../../core/components/focus-scope/FocusScope.js';
import { OverlayContainer } from '../../core/components/OverlayContainer.js';
import { useMergeRefs } from '../../core/hooks/useMergeRefs.js';
import { useOverlayStacking } from '../../core/hooks/useOverlayStacking.js';
import { OverlayStackingProvider } from '../../core/providers/OverlayStackingProvider.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { _useOverlay } from '../hooks/useOverlay.js';

//#region Props
export type DrawerProps = WithChildren &
  StylingProps &
  DataTestId & {
    /** Handler that is called when the Drawer should be dismissed e.g. when pressing `ESC` or clicking on the backdrop. */
    onDismiss: (state: boolean, reason: string) => void;
    /** If the Drawer is currently dismissed or open. */
    isDismissed: boolean;
    /**
     * The side from which the Drawer enters and takes up the most space.
     * @defaultValue 'right'
     */
    placement?: 'left' | 'right';
    /**
     * The width of the Drawer. It supports predefined values and px, vw, rem and %.
     * @defaultValue 'medium'
     */
    width?:
      | 'narrow'
      | 'medium'
      | 'wide'
      | 'full'
      | `${number}px`
      | `${number}vw`
      | `${number}rem`
      | `${number}%`;
  };

//#endregion

//#region styles
const StyledDrawer = styled(motion.div)<{
  $width: string;
  $placement: 'left' | 'right';
}>(
  {
    position: 'absolute',
    height: '100vh',
    overflow: 'auto',
    top: 0,
    backgroundColor: Colors.Background.Base.Default,
    boxShadow: BoxShadows.Surface.Floating.Rest,
  },
  ({ $placement, $width }) => ({
    left: $placement === 'left' ? 0 : 'auto',
    right: $placement === 'right' ? 0 : 'auto',
    borderRadius:
      $placement === 'left'
        ? `0 ${Borders.Radius.Surface.Default} ${Borders.Radius.Surface.Default} 0`
        : `${Borders.Radius.Surface.Default} 0 0 ${Borders.Radius.Surface.Default}`,
    ...getWidthStyles($width),
  }),
);

const StyledBackdrop = /* @__PURE__ */ styled(motion.div)({
  position: 'relative',
  width: '100vw',
  height: '100vh',
  overflow: 'hidden',
  cursor: 'pointer',
  zIndex: Elevations.Default,
  backgroundColor: Colors.Background.Surface.Backdrop,
});
//#endregion

//#region helper functions
const getWidthStyles = (width: string): CSSObject => {
  switch (width) {
    case 'narrow':
      return { width: '25%', minWidth: 'min(calc(100% - 64px), 320px)' };
    case 'medium':
      return { width: '50%', minWidth: 'min(calc(100% - 56px), 640px)' };
    case 'wide':
      return { width: '75%', minWidth: 'min(calc(100% - 48px), 960px)' };
    case 'full':
      return { width: '100%', borderRadius: 'none' };
    default:
      return { width };
  }
};
//#endregion

//#region animations
const slideAnimation = ($placement: 'left' | 'right') => ({
  visible: {
    x: '0',
    transition: {
      duration: AnimationsJS.SlideIn.Duration.Slow,
      ease: AnimationsJS.SlideIn.Easing,
    },
    // Workaround to fix remaining style (transform: translateX(0)) on Drawer
    // as this breaks any child element with position: fixed
    // https://github.com/framer/motion/issues/823
    transitionEnd: {
      x: 0,
    },
  },
  hidden: {
    x: $placement === 'left' ? '-100%' : '100%',
    transition: {
      duration: AnimationsJS.SlideOut.Duration.Slow,
      ease: AnimationsJS.SlideOut.Easing,
    },
  },
});

const fade = {
  fadeIn: {
    // For the opacity we need to use the default value here. Framer motion would complain
    // about too complex values, when transitioning from two custom property values within
    // an rgba value apparently.
    opacity: 1,
    transition: {
      duration: AnimationsJS.SlideIn.Duration.Slow,
      ease: AnimationsJS.FadeIn.Easing,
    },
  },
  fadeOut: {
    opacity: 0,
    transition: {
      duration: AnimationsJS.SlideOut.Duration.Slow,
      ease: AnimationsJS.FadeOut.Easing,
    },
  },
};
//#endregion

/**
 * A drawer component that slides in from the side and displays additional content. Its presence is fully controlled by props.
 * @internal
 */
export const _Drawer = /* @__PURE__ */ forwardRef<HTMLDivElement, DrawerProps>(
  (props, forwardedRef) => {
    const {
      placement = 'right',
      width = 'medium',
      isDismissed,
      onDismiss,
      children,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      ...remainingProps
    }: DrawerProps = props;
    const ref = useRef(null);

    const { overlayProps } = _useOverlay(
      {
        onClose: (reason) => {
          onDismiss(true, reason);
        },
        isOpen: !isDismissed,
        isDismissible: true,
      },
      ref,
    );

    const mergedRefs = useMergeRefs([ref, forwardedRef]);
    const overlayContainerProps = useOverlayStacking(0, 'overlay');

    return (
      <AnimatePresence>
        {!isDismissed && (
          <OverlayContainer
            data-testid="drawer-container"
            {...overlayContainerProps}
          >
            <StyledBackdrop
              variants={fade}
              initial="fadeOut"
              animate="fadeIn"
              exit="fadeOut"
              data-testid="drawer-backdrop"
              {...(overlayProps as Record<string, unknown>)}
            >
              <StyledDrawer
                data-testid={dataTestId}
                ref={mergedRefs}
                $placement={placement}
                variants={slideAnimation(placement)}
                initial="hidden"
                // Prevents that focus is lost when clicking on non-focusable items inside.
                // Probably worth considering moving that to the focusScope when redoing the overlays.
                tabIndex={-1}
                animate="visible"
                exit="hidden"
                $width={width}
                onAnimationComplete={() =>
                  window.dispatchEvent(new Event('animationDone'))
                }
                className={consumerClassName}
                style={consumerStyle}
                {...remainingProps}
              >
                <motion.div
                  variants={fade}
                  initial="fadeOut"
                  animate="fadeIn"
                  exit="fadeOut"
                >
                  <FocusScope autoFocus>
                    <OverlayStackingProvider>
                      {children}
                    </OverlayStackingProvider>
                  </FocusScope>
                </motion.div>
              </StyledDrawer>
            </StyledBackdrop>
          </OverlayContainer>
        )}
      </AnimatePresence>
    );
  },
);
